#include <stdio.h>

#define EMPLEADOS 3
#define DIAS 5

typedef enum {
  LUNES,
  MARTES,
  MIERCOLES,
  JUEVES,
  VIERNES
} TDia;

typedef enum {
  MANANA,
  TARDE,
  NOCHE
} TTurno;

consignas.referencia:
TTurno agenda[][DIAS] = {
  {MANANA, MANANA, TARDE, NOCHE, NOCHE},
  {TARDE, TARDE, TARDE, MANANA, MANANA},
  {NOCHE, MANANA, NOCHE, NOCHE, TARDE}
};

consignas.dado:
TTurno agenda[EMPLEADOS][DIAS] = {
  {MANANA, MANANA, TARDE, NOCHE, NOCHE},
  {TARDE, TARDE, TARDE, MANANA, MANANA},
  {NOCHE, MANANA, NOCHE, NOCHE, TARDE}
};

TTurno agenda[EMPLEADOS][DIAS];
int empleado;
int cantidad = 0;

consignas.referencia:
for (empleado = 0; empleado < EMPLEADOS; empleado++) {
  if (agenda[empleado][VIERNES] == NOCHE) {
    cantidad++;
  }
}

consignas.dado:
TTurno agenda[EMPLEADOS][DIAS];
TDia dia;
int cantidad = 0;

consignas.referencia:
for (dia = LUNES; dia <= VIERNES; dia++) {
  if (agenda[2][dia] == NOCHE) {
    cantidad++;
  }
}

consignas.dado:
TTurno agenda[EMPLEADOS][DIAS];
int empleado;
TDia dia;

consignas.referencia:
for (empleado = 0; empleado < EMPLEADOS; empleado++) {
  for (dia = LUNES; dia <= VIERNES; dia++) {
    switch (agenda[empleado][dia]) {
      case MANANA:
        printf("Manana ");
        break;
      case TARDE:
        printf("Tarde ");
        break;
      case NOCHE:
        printf("Noche ");
        break;
    }
  }
  printf("\n");
}
